import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as c,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"OAuth 攻击面","description":"","frontmatter":{"title":"OAuth 攻击面","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/oauth-attack-surface.md","filePath":"cs/oauth-attack-surface.md","lastUpdated":1789023840000}'),u={name:"cs/oauth-attack-surface.md"};function p(E,a,A,_,C,m){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="oauth-攻击面" tabindex="-1">OAuth 攻击面 <a class="header-anchor" href="#oauth-攻击面" aria-label="Permalink to &quot;OAuth 攻击面&quot;">​</a></h1><div class="epigraph"><p>OAuth 让客户端在用户同意下访问资源服务器，本身不是登录协议。重定向 URI、state、PKCE、混淆代理，决定这次同意是否被掉包。</p><footer>—— RFC 6749；RFC 8252；RFC 6819；RFC 7636 PKCE</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/session-management">会话</a>管第一方会话。缺口是<strong>委托授权</strong>：第三方拿到的是访问令牌，不是用户口令。把 OAuth 当登录要 OpenID Connect，本课先收授权码流的攻击面，不给钓鱼操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放重定向接 authorization code、缺 state 导致 CSRF 同意、公客户端缺 PKCE、令牌进 URL 日志、scope 过宽。缺口是重定向与客户端档案，不是再讲「社交登录」产品。</p><h3 id="access-token-当会话" tabindex="-1">access token 当会话 <a class="header-anchor" href="#access-token-当会话" aria-label="Permalink to &quot;access token 当会话&quot;">​</a></h3><p>资源服务器要验 aud 与签名/内省。把令牌当不透明 cookie 乱存会回到 JWT 课的陷阱。</p><p><span class="marginnote">RFC 6819 威胁模型。PKCE 原为公客户端，现成建议默认。本课禁止配置恶意客户端的教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按授权码流标检查点：注册精确 redirect_uri、state/nonce、PKCE、后信道 token、最小 scope。对照隐式流为何退出。SAML 下一课是企业里另一套 XML 委托。</p>',12)),(e(),l(d,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20UA%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%22%5D%20--%3E%20AS%5B%22%E6%8E%88%E6%9D%83%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A%20%20AS%20--%3E%20CODE%5B%22%E6%8E%88%E6%9D%83%E7%A0%81%E5%9B%9E%20redirect%22%5D%0A%20%20CODE%20--%3E%20PKCE%5B%22%E7%A0%81%2Bverifier%20%E6%8D%A2%E4%BB%A4%E7%89%8C%22%5D%0A%20%20PKCE%20--%3E%20RS%5B%22%E8%B5%84%E6%BA%90%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>委托把身份提供者做成 TCB。失败在绑定：码与客户端、码与 redirect、令牌与 aud。下一课 SAML：断言与 XML 包装的同类绑定问题。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 grant 类型。SAML 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>会话是第一方；OAuth 是委托。</li><li>redirect、state、PKCE、scope 是合同。</li><li>OAuth≠登录；OIDC 才带身份令牌。</li><li>下一课 SAML。</li><li>出处：RFC 6749；RFC 6819；RFC 7636；RFC 8252。</li></ul>',8))])}const P=s(u,[["render",p]]);export{k as __pageData,P as default};
